import {createChatOrchestrator, PromptBuilder} from '../index.js';
import type {AIProvider, MessageChunk, TurnUsageMetadata} from '../index.js';

// specs/hal-engine-config-hooks/spec.md#10
it('exposes turn usage as the hook total', async () => {
  const usage: TurnUsageMetadata = {inputTokens: 2, outputTokens: 3, totalTokens: 5};
  const provider: AIProvider = {
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      yield {type: 'stop', stopReason: 'end_turn', usage};
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
  let total: TurnUsageMetadata | undefined;
  const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'Test'}), undefined, {
    hooks: {afterModelResponse: async (_session, _text, turnUsage) => { total = turnUsage; }},
  });
  await orchestrator.processMessage({
    sessionId: 's', userId: 'u',
    entries: [{role: 'user', content: 'Hi', timestamp: '2026-01-01T00:00:00.000Z'}],
  });
  expect(total).toEqual(usage);
});
EOF
 timeout 300 npm test -- --runInBand --runTestsByPath src/orchestration/turnUsageContract.test.ts"
